on conflict (part_number) do update set name=excluded.name,description=excluded.description,engine_models=excluded.engine_models,technical_group=excluded.technical_group,source_name=excluded.source_name,source_url=excluded.source_url,source_note=excluded.source_note,verification_status='REFERENCE',application_type=excluded.application_type,application_evidence=excluded.application_evidence,application_source_url=excluded.application_source_url,compatible_models=excluded.compatible_models,updated_at=now();

on conflict (sku) do update set name=excluded.name,brand=excluded.brand,category=excluded.category,machine_model=excluded.machine_model,description=excluded.description,image_url=excluded.image_url,application_type=excluded.application_type,application_evidence=excluded.application_evidence,application_source_url=excluded.application_source_url,updated_at=now();
