insert into public.part_catalog
 (part_number,name,description,engine_models,technical_group,source_name,source_url,source_note,verification_status,application_type,application_evidence,application_source_url,compatible_models)
values
('134-0467','Cat Unit Injector Hydraulic Pump Group','Cat PUMP GP-INJ. Cat product page lists compatible Truck Engine 3126E/3126/3126B and Engine 3126E. Cat page compares Cat Reman 30R-0400; not an asserted universal interchange.',ARRAY['3126E','3126','3126B'],'سیستم سوخت‌رسانی - پمپ هیدرولیک انژکتور','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/134-0467','Exact Cat product page identifies PUMP GP-INJ, Brand Cat, compatible Truck Engine 3126E/3126/3126B and Engine 3126E. No usable product image in retrieved version; reference-only.', 'REFERENCE','LAND','CAT compatible model list contains truck/industrial engine classes and no Marine Engine group.','https://parts.cat.com/en/catcorp/product/134-0467',ARRAY['3126E','3126','3126B']),
('8N-7005','Cat Fuel Valve Nozzle','Cat Direct Injection Fuel Valve Nozzle; length 8.7 in, height 1.5 in. CAT explicitly lists Marine Engine 3306B/3304/3306/3304B and non-marine equipment groups.',ARRAY['3306B','3304','3306','3304B'],'سیستم سوخت‌رسانی - نازل انژکتور','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/8N-7005','Exact Cat page identifies Fuel Valve Nozzle, direct-injection type, length 8.7 in, height 1.5 in. Marine Engine group lists 3306B/3304/3306/3304B.','REFERENCE','BOTH','CAT Compatible Models explicitly includes Marine Engine 3306B/3304/3306/3304B and non-marine machine/engine groups.','https://parts.cat.com/en/catcorp/product/8N-7005',ARRAY['3306B','3304','3306','3304B']),
('392-0206','Cat Injector Group','Cat Fuel Injector Group; length 14.8 in, height 3.0 in. CAT lists Marine Engine 3512/3508/3508B/3516B/3512B, Marine Auxiliary 3512B/3508B/3516B and non-marine applications.',ARRAY['3512','3508','3508B','3516B','3512B'],'سیستم سوخت‌رسانی - مجموعه انژکتور','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/392-0206','Exact Cat page identifies Injector Group, dimensions 14.8 × 3.0 in. Marine Engine and Marine Auxiliary groups explicitly listed. Cat Reman 11R-0280 and 20R-1270 are separate reman options, not asserted direct interchangeable SKUs.','REFERENCE','BOTH','CAT Compatible Models explicitly lists Marine Engine and Marine Auxiliary plus non-marine generator/industrial groups.','https://parts.cat.com/en/catcorp/product/392-0206',ARRAY['3512','3508','3508B','3516B','3512B']),
('20R-0849','Cat Reman Fuel Injector','Cat Reman Fuel Injector; length 14.8 in, height 3.0 in. Compatible models include D11R/D11N, 5230B/5130B, 785/777/789 truck families, 776D/784C, 854G and 992G. No Marine Engine group in retrieved page.',ARRAY['D11R','D11N','5230B','5130B','785','777','789','789C','789D','777C','777B','785C','777D','785D','785B','776D','784C','854G','992G'],'سیستم سوخت‌رسانی - انژکتور بازسازی‌شده','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/20R-0849','Exact Cat page identifies Cat Reman Fuel Injector; Reman condition is part of official product identity. Dimensions 14.8 × 3.0 in. Compatible-model groups are land machine/truck applications; no Marine Engine group in retrieved page.','REFERENCE','LAND','CAT Compatible Models lists land machine/truck groups and no Marine Engine group.','https://parts.cat.com/en/catcorp/product/20R-0849',ARRAY['D11R','D11N','5230B','5130B','785','777','789','789C','789D','777C','777B','785C','777D','785D','785B','776D','784C','854G','992G']),
('20R-4179','Cat Reman Mechanical Electronic Fuel Injector','Cat Reman Mechanical Electronic Fuel Injector; length 21.1 in, height 7.3 in. CAT explicitly lists Marine Engine 3616/3612 and Marine Auxiliary 3608, plus generator-set applications.',ARRAY['3616','3612','3608','3606'],'سیستم سوخت‌رسانی - انژکتور بازسازی‌شده','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/20R-4179','Exact Cat page identifies Reman Mechanical Electronic Fuel Injector, Brand Cat Reman, dimensions 21.1 × 7.3 in. Marine Engine 3616/3612 and Marine Auxiliary 3608 explicitly listed.','REFERENCE','BOTH','CAT Compatible Models explicitly lists Marine Engine and Marine Auxiliary plus generator-set engine groups.','https://parts.cat.com/en/catcorp/product/20R-4179',ARRAY['3616','3612','3608','3606']),
('324-0532','Cat Fuel Injection Pump Group','Cat Fuel Injection Pump Group; length 15.7 in, height 6.2 in. Compatible model families include C4.4/C6.6, 420E/430E/450E, D5K/D4K/D3K, IT14G, TH407C and other equipment. No Marine Engine group in retrieved page.',ARRAY['C4.4','C6.6','420E','430E','450E','D5K','D4K','D3K','IT14G','IT14G2','TH407C','M315D'],'سیستم سوخت‌رسانی - پمپ انژکتور','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/324-0532','Exact Cat page identifies Fuel Pump Group / Cat Fuel Injection Pump, dimensions 15.7 × 6.2 in. Cat Reman 10R-7659 is displayed as a separate reman option; no universal interchange inferred. No Marine Engine group in retrieved compatible models.','REFERENCE','LAND','CAT Compatible Models lists land machine/engine groups and no Marine Engine group.','https://parts.cat.com/en/catcorp/product/324-0532',ARRAY['C4.4','C6.6','420E','430E','450E','D5K','D4K','D3K','IT14G','IT14G2','TH407C','M315D']),
('375-2647','Cat Fuel Injection Pump','Cat Fuel Injection Pump used in Fuel Unit; length 11.0 in, height 16.0 in. Compatible models include C7.1, C4.4, 3512B generator-set and land equipment families. No Marine Engine group in retrieved page.',ARRAY['C7.1','C4.4','3512B'],'سیستم سوخت‌رسانی - پمپ انژکتور','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/375-2647','Exact Cat page identifies Fuel Injection Pump used in Fuel Unit, dimensions 11.0 × 16.0 in. Compatible model listing includes C7.1, C4.4 and 3512B generator-set engine; no Marine Engine group in retrieved result.','REFERENCE','LAND','CAT Compatible Models lists generator/industrial and land equipment groups; no Marine Engine group in retrieved page.','https://parts.cat.com/en/catcorp/product/375-2647',ARRAY['C7.1','C4.4','3512B']),
('591-2386','Cat 24V Diesel Exhaust Fluid Pump','Cat 24V Diesel Exhaust Fluid Pump; 12-position AMP connector; maximum flow 7.2 kg/h; dimensions 5.3 in high × 8.7 in long × 8.2 in wide. No Marine Engine group appears in retrieved CAT compatible-model list.',ARRAY['C15','C18','C7.1','C9.3','C3.6'],'سیستم پس‌پالایش اگزوز - پمپ DEF','Cat Parts Store (official); Off Road Equipment public 500-part index','https://parts.cat.com/en/catcorp/product/591-2386','Exact Cat page identifies 24V Diesel Exhaust Fluid Pump, 12-position AMP connector, max flow 7.2 kg/h, dimensions 5.3 × 8.7 × 8.2 in. Compatible models include multiple machine/engine groups. No Marine Engine group in retrieved page.','REFERENCE','LAND','CAT Compatible Models lists land machine/engine groups and no Marine Engine group.','https://parts.cat.com/en/catcorp/product/591-2386',ARRAY['C15','C18','C7.1','C9.3','C3.6'])
